def srcs(*ids):
    return [src(i, *S[i]) for i in ids]


def invariant(where):
    return p(f'For a site in {where}, Invariant checks how it gets power and the evidence behind that path (the distribution or transmission connection, the open access route, the nearest substations), screens seismic zone, flood history, groundwater status and airport height limits, and maps the central and state approvals the project needs, with the authority behind each one.')


def facts(rows, *ids):
    return table(['Item', f'Detail (checked {CHECKED})'], rows, *ids)


